export async function uploadCsv(client: BlobServiceClient, container: string, name: string, path: string): Promise<void> {
  const blob = client.getContainerClient(container).getBlockBlobClient(name);
  let lastErr: unknown;
  for (let i = 0; i < 3; i++) {
    try {
      await blob.uploadFile(path);
      return;
    } catch (e) {
      lastErr = e;
      console.error(`uploadCsv intento ${i + 1} falló`, e);
    }
  }
  throw lastErr;
}

