export function parseFilters(raw: string): Record<string, string> {
  try {
    return JSON.parse(raw);
  } catch {
    return {};
  }
}

export function applyFilters(rows: { estado: string }[], f: Record<string, string>): { estado: string }[] {
  return f.estado ? rows.filter((r) => r.estado === f.estado) : rows;
}
